import {taxonomy,domains,catalogLabel,matches} from './catalog.js';
import {icons,iconSvg,pickIcon} from './identity.js';
import {design,colors,presets,sections} from './design.js';
let currentDesign=design();
const app=document.querySelector('#app');let ar=(new URLSearchParams(location.search).get('lang')||document.documentElement.lang)!=='en';const tr=(en,a)=>ar?a:en;const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));document.documentElement.lang=ar?'ar':'en';document.documentElement.dir=ar?'rtl':'ltr';document.body.classList.toggle('light',localStorage.theme==='light');document.querySelector('#lang').hidden=false;document.querySelector('#lang-link')?.remove();document.querySelector('#lang').onclick=()=>{localStorage.lang=ar?'en':'ar';const u=new URL(location.href);u.searchParams.set('lang',localStorage.lang);location.href=u.href};document.querySelector('#theme').onclick=()=>{document.body.classList.toggle('light');localStorage.theme=document.body.classList.contains('light')?'light':'dark';applySite(currentDesign)};document.querySelectorAll('nav a').forEach((a,i)=>a.textContent=[tr('Work','الأعمال'),tr('Services','الخدمات'),tr('Workspace','مساحة العمل')][i]);
async function api(p,data){const r=await fetch('/api/'+p,data===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});const v=await r.json();if(!r.ok)throw Error(v.error);return v}const kinds={brand:['Brands','العلامات'],page:['Pages','الصفحات'],project:['Projects','المشاريع'],product:['Products','المنتجات'],service:['Services','الخدمات'],article:['Articles','المقالات'],learning:['Learning tracks','مسارات التعلم'],resource:['Resources','المصادر'],study:['Study journal','سجل الدراسة'],client:['Clients','العملاء'],inquiry:['Inquiries','الطلبات'],proposal:['Proposals','العروض'],agreement:['Agreements','الاتفاقيات'],task:['Tasks','المهام'],milestone:['Milestones','المراحل'],social:['Social drafts','مسودات التواصل'],agent:['AI agent records','سجلات الوكلاء'],experience:['Showcases','العروض التفاعلية'],notification:['Notifications','الإشعارات'],skill:['Skills','المهارات'],achievement:['Achievements','الإنجازات'],certification:['Certifications','الشهادات'],education:['Education','التعليم'],career:['Career','الخبرات المهنية']};const localized=(x,k)=>x[(ar?'ar_':'en_')+k]||x[k];const statusLabel=x=>({deleted:tr('Trash','سلة المحذوفات'),draft:tr('Draft','مسودة'),published:tr('Published','منشور'),archived:tr('Archived','مؤرشف'),in_progress:tr('In progress','قيد العمل'),under_review:tr('Under review','قيد المراجعة'),testing:tr('Testing','اختبار'),completed:tr('Completed','مكتمل'),new:tr('New','جديد'),approved:tr('Approved','معتمد')})[x]||x;const label=k=>tr(...(kinds[k]||[k,k]));const options=(arr,v)=>arr.map(x=>`<option value="${esc(x)}" ${x===v?'selected':''}>${esc(statusLabel(x))}</option>`).join('');const msg=e=>{const n=document.querySelector('#message');if(n)n.textContent=e.message||e};
async function home(){const [site,rows]=await Promise.all([api('site'),api('public')]);applySite(site);const identity=rows.find(x=>x.kind==='brand'&&x.brand==='personal');const groups=[['page','about'],['project','work'],['product','products'],['service','services'],['article','insights'],['experience','experiences']];app.innerHTML=`<section class="hero"><div class="hero-copy"><div class="eyebrow"><span class="signal"></span> ${tr('PERSONAL TECHNOLOGY ECOSYSTEM','منظومة تكنولوجية شخصية')}</div><h1>${esc(site[ar?'headline_ar':'headline_en']||tr('Beyond ideas.','أبعد من الأفكار.'))}<br><em>${esc(site[ar?'subline_ar':'subline_en']||tr('Into impact.','نحو التأثير.'))}</em></h1><p>${esc(identity && localized(identity,'body'))||tr('One space for technology, research, data and meaningful digital experiences.','مساحة واحدة للتكنولوجيا والبحث والبيانات والتجارب الرقمية المؤثرة.')}</p><div class="actions"><a class="secondary" href="#identity">${tr('Meet me','تعرّف عليّ')}</a><a class="primary" href="/projects?lang=${ar?'ar':'en'}">${tr('Explore work','استكشف الأعمال')} ↗</a><a class="secondary" href="#contact">${tr('Start a project','ابدأ مشروعًا')}</a></div></div><div class="visual" aria-hidden="true"><div class="orbit o1"></div><div class="orbit o2"></div><div class="orbit o3"></div><div class="core"><svg viewBox="0 0 100 100" aria-hidden="true"><path d="M22 18L78 82M78 18L22 82M50 5V23M50 77V95"/><circle cx="50" cy="50" r="6"/></svg></div><span class="tag t1">${tr('DATA / AI','البيانات / الذكاء')}</span><span class="tag t2">${tr('ENGINEERING','الهندسة')}</span><span class="tag t3">${tr('RESEARCH','البحث')}</span></div></section><div class="strip"><span>${tr('01 / DESIGN','01 / التصميم')}</span><span>${tr('02 / TECHNOLOGY','02 / التكنولوجيا')}</span><span>${tr('03 / INTELLIGENCE','03 / الذكاء')}</span><span>${tr('04 / IMPACT','04 / الأثر')}</span></div>${profile(site,rows)}${groups.map(([k,id],i)=>{const items=rows.filter(x=>x.kind===k);return `<section class="content-section" id="${id}"><div class="section-head"><div><div class="eyebrow">0${i+1} / ${esc(label(k))}</div><h2>${label(k)}</h2></div><span class="muted">${items.length} ${tr('published','منشور')}</span>${k==='project'?`<a class="secondary" href="/projects?lang=${ar?'ar':'en'}">${tr('View all projects','عرض كل المشاريع')} ↗</a>`:''}</div>${items.length?`<div class="grid">${items.map((x,j)=>`<article class="card showcase"><div class="card-index">0${j+1} / ${esc(label(k))}</div><span class="identity-icon">${iconSvg(x.icon||pickIcon(localized(x,'title'),k))}</span><h3>${esc(localized(x,'title'))}</h3><p>${esc(localized(x,'body'))}</p>${k==='project'?projectActions(x):''}</article>`).join('')}</div>`:`<div class="empty">${tr('New work will appear here when published.','سيظهر المحتوى هنا عند نشره.')}</div>`}</section>`}).join('')}<section class="contact" id="contact"><div><div class="eyebrow">${tr('LET’S CONNECT','لنتواصل')}</div><h2>${tr('Build something meaningful.','لنبنِ شيئًا ذا قيمة.')}</h2><p>${tr('Tell me about your next project.','أخبرني عن مشروعك القادم.')}</p></div><form id="inquiry"><label>${tr('Project title','عنوان المشروع')}<input name="title" required maxlength="150"></label><label>${tr('Email','البريد الإلكتروني')}<input name="email" type="email" required></label><label>${tr('Requirements','المتطلبات')}<textarea name="body" required maxlength="5000"></textarea></label><input class="trap" name="website" tabindex="-1" autocomplete="off" aria-hidden="true"><button class="primary">${tr('Send inquiry','إرسال الطلب')} ↗</button><p id="message" role="status"></p></form></section>`;document.querySelector('#inquiry').onsubmit=async e=>{e.preventDefault();try{await api('inquiry',{...Object.fromEntries(new FormData(e.target)),brand:'personal'});e.target.reset();msg(tr('Request received','تم استلام الطلب'))}catch(e){msg(e)}}}
async function website(brand){const rows=await api('public?brand='+brand);const identity=rows.find(x=>x.kind==='brand');app.innerHTML=`<section class="hero"><div class="eyebrow">${esc(brand.toUpperCase())}</div><h1>${esc(identity?.title||brand)}</h1><p>${esc(identity?.body||'')}</p><a class="primary" href="#contact">${tr('Request a solution','اطلب حلًا')}</a></section>${['page','project','product','service','article','experience'].map(k=>{const items=rows.filter(x=>x.kind===k);return `<section><h2>${label(k)}</h2>${items.length?`<div class="grid">${items.map(x=>`<article class="card"><h3>${esc(localized(x,'title'))}</h3><p>${esc(localized(x,'body'))}</p></article>`).join('')}</div>`:`<p>${tr('No published items yet.','لا توجد عناصر منشورة بعد.')}</p>`}</section>`}).join('')}<section id="contact"><h2>${tr('Contact & custom requests','التواصل والطلبات المخصصة')}</h2><form id="inquiry"><input name="title" required maxlength="150" placeholder="${tr('Project title','عنوان المشروع')}"><input name="email" type="email" required placeholder="${tr('Email','البريد الإلكتروني')}"><textarea name="body" required maxlength="5000" placeholder="${tr('Requirements, budget and timeline','المتطلبات والميزانية والمدة')}"></textarea><button class="primary">${tr('Submit request','إرسال الطلب')}</button></form><p id="message" role="status"></p></section>`;document.querySelector('#inquiry').onsubmit=async e=>{e.preventDefault();try{await api('inquiry',{...Object.fromEntries(new FormData(e.target)),brand});e.target.reset();msg(tr('Request received','تم استلام الطلب'))}catch(e){msg(e)}}}
let records=[],selected='overview';async function admin(){try{records=await api('records');dashboard()}catch{app.innerHTML=`<div class="card"><h2>${tr('Owner login','دخول المالك')}</h2><form id="login"><input type="password" name="password" required autocomplete="current-password" placeholder="${tr('Owner password','كلمة المرور')}"><button class="primary">${tr('Sign in','دخول')}</button></form><p id="message" role="status"></p></div>`;document.querySelector('#login').onsubmit=async e=>{e.preventDefault();try{await api('login',Object.fromEntries(new FormData(e.target)));await admin()}catch(e){msg(e)}}}}
function dashboard(){app.innerHTML=`<div class="admin-title"><div class="eyebrow">${esc(ar?(currentDesign.site_name_ar||currentDesign.site_name):currentDesign.site_name)+' / '+tr('PRIVATE WORKSPACE','مساحة خاصة')}</div><h1>${tr('Command center','مركز التحكم')}</h1><p>${tr('Manage your entire digital ecosystem.','إدارة منظومتك الرقمية بالكامل.')}</p></div><div class="toolbar"><button id="logout">${tr('Logout','خروج')}</button><button id="export">${tr('Export data','تصدير البيانات')}</button><button id="audit">${tr('Audit log','سجل العمليات')}</button></div><div class="layout"><aside class="side">${['overview','identity','design','import','showcase','storage','data-index',...Object.keys(kinds)].map(k=>`<button data-kind="${k}" class="${k===selected?'active':''}">${k==='overview'?tr('Overview','نظرة عامة'):k==='identity'?tr('My identity','هويتي الشخصية'):k==='design'?tr('Design studio','استوديو التصميم'):k==='import'?tr('Project import studio','استوديو استيراد المشاريع'):k==='showcase'?tr('Live showcase & activity','العروض الحية والإنجازات'):k==='storage'?tr('Data & GitHub','البيانات وGitHub'):k==='data-index'?tr('Data catalog','فهرس البيانات'):label(k)}</button>`).join('')}</aside><section id="panel"></section></div><p id="message" role="status"></p>`;document.querySelectorAll('[data-kind]').forEach(b=>b.onclick=()=>{selected=b.dataset.kind;api('site').then(applySite).then(dashboard).catch(msg)});document.querySelector('#logout').onclick=async()=>{await api('logout',{});location.reload()};document.querySelector('#export').onclick=async()=>{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(await api('export'),null,2)],{type:'application/json'}));a.download='ecosystem-export.json';a.click();URL.revokeObjectURL(a.href)};document.querySelector('#audit').onclick=async()=>{const a=await api('audit');document.querySelector('#panel').innerHTML=`<h2>${tr('Audit log','سجل العمليات')}</h2>${a.map(x=>`<p>${esc(x.created)} · ${esc(x.action)}</p>`).join('')}`};const p=document.querySelector('#panel');if(selected==='design'){designStudio(p);return}if(selected==='identity'){identityEditor(p);return}if(selected==='import'){importStudio(p);return}if(selected==='showcase'){showcaseEditor(p);return}if(selected==='storage'){storageStudio(p);return}if(selected==='data-index'){dataIndexStudio(p);return}if(selected==='overview'){p.innerHTML=`<div class="grid">${['project','service','inquiry','client','learning','task'].map(k=>`<div class="card"><small>${label(k)}</small><h2>${records.filter(x=>x.kind===k&&!['archived','deleted'].includes(x.status)).length}</h2></div>`).join('')}</div>`;return}p.innerHTML=`<h2>${label(selected)}</h2><button id="add" class="primary">${tr('New record','إضافة سجل')}</button><div id="editor"></div><div class="grid">${records.filter(x=>x.kind===selected).map(x=>`<article class="card"><small>${esc(tr('Personal','شخصي'))} · ${esc(statusLabel(x.status))}</small><span class="identity-icon">${iconSvg(x.icon||pickIcon(localized(x,'title'),x.kind))}</span><h3>${esc(localized(x,'title'))}</h3><p>${esc(localized(x,'body'))}</p>${x.kind==='inquiry'&&x.status==='approved'?`<button data-convert="${x.id}">${tr('Create project','تحويل إلى مشروع')}</button>`:''}<button data-history="${x.id}">${tr('History','السجل')}</button>${x.status==='deleted'?'':`<button data-edit="${x.id}">${tr('Edit / archive','تعديل / أرشفة')}</button>`}${x.kind==='project'&&x.status!=='deleted'?`<button data-data-builder="${x.id}">${tr('Build CSV experience','بناء تجربة CSV')}</button>`:''}${recordActions(x)}</article>`).join('')}</div>`;document.querySelectorAll('[data-convert]').forEach(b=>b.onclick=async()=>{try{await api('convert',{id:b.dataset.convert});records=await api('records');dashboard();msg(tr('Project created','تم إنشاء المشروع'))}catch(e){msg(e)}});bindRecordActions();document.querySelectorAll('[data-data-builder]').forEach(b=>b.onclick=()=>dataBuilder(b.dataset.dataBuilder));document.querySelectorAll('[data-history]').forEach(b=>b.onclick=()=>historyEditor(b.dataset.history));document.querySelector('#add').onclick=()=>edit({kind:selected});document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>edit(records.find(x=>x.id===b.dataset.edit)))}
function edit(x){document.querySelector('#editor').innerHTML=`<form class="card" id="record"><label>${tr('Title','العنوان')}<input name="title" required maxlength="150" value="${esc(x.title)}"></label><input type="hidden" name="brand" value="${esc(x.brand||'personal')}"><label>${tr('Details','التفاصيل')}<textarea name="body" maxlength="30000">${esc(x.body)}</textarea></label>${['ar','en'].map(l=>`<label>${l==='ar'?tr('Arabic title','العنوان العربي'):tr('English title','العنوان الإنجليزي')}<input name="${l}_title" maxlength="150" value="${esc(x[l+'_title'])}"></label><label>${l==='ar'?tr('Arabic details','التفاصيل العربية'):tr('English details','التفاصيل الإنجليزية')}<textarea name="${l}_body" maxlength="30000">${esc(x[l+'_body'])}</textarea></label>`).join('')}<label>${tr('Icon','الأيقونة')}<select name="icon">${['',...Object.keys(icons)].map(i=>`<option value="${i}" ${i===(x.icon||'')?'selected':''}>${i?iconLabel(i):tr('Automatic','تلقائي')}</option>`).join('')}</select></label><div id="icon-preview" class="identity-icon" aria-label="${tr('Icon preview','معاينة الأيقونة')}"></div><label>${tr('Status','الحالة')}<select name="status">${options(['draft','in_progress','under_review','testing','completed','new','approved','archived',...(['brand','page','project','product','service','article','experience','skill','achievement','certification','education','career'].includes(x.kind)?['published']:[])],x.status)}</select></label><button class="primary">${tr('Save','حفظ')}</button></form>`;const form=document.querySelector('#record');form.querySelector('button.primary').insertAdjacentHTML('beforebegin',catalogEditor(x));const preview=()=>form.querySelector('#icon-preview').innerHTML=iconSvg(form.elements.icon.value||pickIcon(form.elements.title.value,x.kind));form.elements.icon.onchange=preview;form.elements.title.oninput=preview;preview();form.onsubmit=async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(e.target));if(b.status==='published'&&!confirm(tr('Publish publicly?','نشر للعامة؟')))return;try{const catalog={mode:b.cat_mode,domains:b.cat_domains.split(',').map(x=>x.trim()).filter(Boolean),technologies:b.cat_tech.split(',').map(x=>x.trim()).filter(Boolean),tags:b.cat_tags.split(',').map(x=>x.trim()).filter(Boolean),featured:b.cat_featured==='on'};for(const k of Object.keys(b))if(k.startsWith('cat_'))delete b[k];await api('records',{...b,catalog,kind:x.kind,id:x.id});records=await api('records');dashboard();msg(tr('Saved','تم الحفظ'))}catch(e){msg(e)}}}
function applySite(raw){const site=design(raw);const b=document.body;for(const [k,v] of Object.entries(site))if(['font','motion','layout','radius','hero_style','palette'].includes(k))b.dataset[k]=v;const mode=b.classList.contains('light')?'light':'dark';for(const k of colors)b.style.setProperty('--'+k,site[mode+'_colors'][k]);const name=ar?(site.site_name_ar||site.site_name):site.site_name;document.querySelectorAll('.logo').forEach(el=>el.textContent='✦ '+name+'.');document.querySelectorAll('.portrait-mark').forEach(el=>el.textContent=site.monogram);document.querySelectorAll('.assistant-toggle,.assistant-head strong').forEach(el=>el.textContent='✳ '+(ar?(site.assistant_name_ar||site.assistant_name):site.assistant_name));currentDesign=site;}
function arrangeSite(){if(location.pathname!=='/')return;const d=currentDesign;for(const id of d.section_order){const el=document.getElementById(id);if(el){app.append(el);el.hidden=d.hidden_sections.includes(id)}}for(const a of document.querySelectorAll('a[href*="#"]')){const id=a.hash.slice(1);if(sections.includes(id))a.hidden=d.hidden_sections.includes(id)}}
const sectionNames={identity:['Identity','الهوية'],about:['About','نبذة'],work:['Projects','المشاريع'],products:['Products','المنتجات'],services:['Services','الخدمات'],insights:['Articles','المقالات'],experiences:['Experiences','التجارب'],live:['Live work & activity','الأعمال الحية والأنشطة'],contact:['Contact','التواصل']};
async function designStudio(p){try{let base=design(await api('site')),draft=structuredClone(base);const title=k=>tr(...sectionNames[k]);const fields=[['site_name','Site name','اسم الموقع'],['site_name_ar','Arabic site name','اسم الموقع بالعربية'],['monogram','Personal mark (1–6 characters)','الرمز الشخصي (حتى 6 أحرف)'],['assistant_name','Assistant name','اسم المساعد'],['assistant_name_ar','Arabic assistant name','اسم المساعد بالعربية']];const choices=[['font','Typography','الخط',[['system','Modern','حديث'],['serif','Editorial','تحريري'],['mono','Technical','تقني']]],['motion','Motion','الحركة',[['full','Full','كاملة'],['subtle','Subtle','هادئة'],['off','Off','متوقفة']]],['layout','Page width','عرض الصفحة',[['wide','Wide','واسع'],['focused','Focused','مركّز']]],['radius','Corners','الحواف',[['sharp','Sharp','حادة'],['soft','Soft','ناعمة'],['round','Round','دائرية']]],['hero_style','Hero visual','شكل الرئيسية',[['orbit','Orbital','مدارات'],['minimal','Minimal','بسيط'],['grid','Grid','شبكي']]],['default_theme','Default appearance','المظهر الافتراضي',[['dark','Dark','داكن'],['light','Light','فاتح']]],['default_language','Default language','اللغة الافتراضية',[['ar','Arabic','العربية'],['en','English','الإنجليزية']]]];const colorNames={bg:['Background','الخلفية'],panel:['Cards','البطاقات'],ink:['Text','النص'],muted:['Secondary text','النص الثانوي'],line:['Borders','الحدود'],accent:['Primary accent','اللون الرئيسي'],accent2:['Secondary accent','اللون المكمل']};function render(){p.innerHTML=`<div class="studio-banner"><div class="eyebrow">DESIGN / CONTROL</div><h2>${tr('Make it yours.','اصنع هويتك بطريقتك.')}</h2><p>${tr('Preview changes privately, then publish when ready.','عاين التغييرات بشكل خاص ثم انشرها عندما تصبح جاهزة.')}</p></div><div class="design-columns"><form class="card" id="design-form"><h3>${tr('Brand identity','هوية الموقع')}</h3>${fields.map(([k,en,a])=>`<label>${tr(en,a)}<input name="${k}" value="${esc(draft[k])}" maxlength="${k==='monogram'?6:k.startsWith('assistant')?40:60}"></label>`).join('')}<h3>${tr('Appearance','المظهر')}</h3><label>${tr('Color collection','مجموعة الألوان')}<select name="palette">${['ocean','ember','mono','aurora','custom'].map(k=>`<option ${draft.palette===k?'selected':''}>${k}</option>`).join('')}</select></label>${['dark','light'].map(mode=>`<h4>${mode==='dark'?tr('Dark palette','ألوان المظهر الداكن'):tr('Light palette','ألوان المظهر الفاتح')}</h4><div class="color-grid">${colors.map(k=>`<label>${tr(...colorNames[k])}<input type="color" name="${mode}_${k}" value="${draft[mode+'_colors'][k]}"></label>`).join('')}</div>`).join('')}${choices.map(([k,en,a,opts])=>`<label>${tr(en,a)}<select name="${k}">${opts.map(([v,e,a])=>`<option value="${v}" ${draft[k]===v?'selected':''}>${tr(e,a)}</option>`).join('')}</select></label>`).join('')}<h3>${tr('Public sections','أقسام الموقع العامة')}</h3><div id="section-sort">${draft.section_order.map((k,i)=>`<div class="section-sort-row"><label class="sync-choice"><input type="checkbox" data-visible="${k}" ${draft.hidden_sections.includes(k)?'':'checked'}>${title(k)}</label><button type="button" data-move="${i},-1" ${i===0?'disabled':''} aria-label="${tr('Move up','تحريك لأعلى')}">↑</button><button type="button" data-move="${i},1" ${i===sections.length-1?'disabled':''} aria-label="${tr('Move down','تحريك لأسفل')}">↓</button></div>`).join('')}</div><button class="primary">${tr('Publish configuration','نشر الإعدادات')}</button><button type="button" id="discard-design">${tr('Discard preview','إلغاء المعاينة')}</button></form><div class="design-preview card"><div class="eyebrow">${tr('PRIVATE LIVE PREVIEW','معاينة حية خاصة')}</div><h2 id="preview-name"></h2><div class="preview-orbit" id="preview-mark"></div><p>${tr('Technology. Knowledge. Impact.','تكنولوجيا. معرفة. تأثير.')}</p><div class="primary">${tr('Explore work','استكشف الأعمال')}</div><div id="preview-sections"></div></div></div><div class="card design-recovery"><h3>${tr('Version history & recovery','تاريخ الإعدادات والاستعادة')}</h3><p>${tr('Resetting design never deletes projects or profile content.','إعادة ضبط التصميم لا تحذف المشاريع أو محتوى التعريف الشخصي.')}</p><div class="toolbar"><button id="reset-design">${tr('Reset design to defaults','استعادة التصميم الافتراضي')}</button><button id="download-design">${tr('Export design JSON','تصدير إعدادات التصميم')}</button><label>${tr('Import design JSON','استيراد إعدادات تصميم')}<input id="upload-design" type="file" accept=".json,application/json"></label></div><div id="design-history"></div></div>`;const f=p.querySelector('#design-form');function preview(){applySite(draft);p.querySelector('#preview-name').textContent=ar?(draft.site_name_ar||draft.site_name):draft.site_name;p.querySelector('#preview-mark').textContent=draft.monogram;p.querySelector('#preview-sections').textContent=draft.section_order.filter(k=>!draft.hidden_sections.includes(k)).map(title).join(' / ')}function capture(){for(const [k] of fields)draft[k]=f.elements[k].value;for(const [k] of choices)draft[k]=f.elements[k].value;for(const mode of ['dark','light'])for(const k of colors)draft[mode+'_colors'][k]=f.elements[mode+'_'+k].value;draft.palette=f.elements.palette.value;draft.hidden_sections=[...f.querySelectorAll('[data-visible]:not(:checked)')].map(x=>x.dataset.visible)}f.oninput=e=>{capture();if(e.target.name==='palette'&&draft.palette!=='custom'){draft.dark_colors=Object.fromEntries(colors.map((k,i)=>[k,presets[draft.palette][i]]));render();return}if(e.target.type==='color'){draft.palette='custom';f.elements.palette.value='custom'}preview()};f.querySelectorAll('[data-move]').forEach(b=>b.onclick=()=>{capture();const [i,delta]=b.dataset.move.split(',').map(Number);const a=draft.section_order;[a[i],a[i+delta]]=[a[i+delta],a[i]];render()});f.onsubmit=async e=>{e.preventDefault();capture();if(!confirm(tr('Publish these settings?','نشر هذه الإعدادات؟')))return;try{base=design(await api('site',draft));draft=structuredClone(base);render();msg(tr('Published','تم النشر'))}catch(e){msg(e)}};p.querySelector('#discard-design').onclick=()=>{draft=structuredClone(base);render()};p.querySelector('#reset-design').onclick=async()=>{if(!confirm(tr('Restore default design? Content stays intact.','استعادة التصميم الافتراضي؟ سيبقى المحتوى محفوظًا.')))return;try{base=design(await api('site/reset',{confirm:'RESET DESIGN'}));draft=structuredClone(base);render();msg(tr('Reset complete','تمت الاستعادة'))}catch(e){msg(e)}};p.querySelector('#download-design').onclick=()=>{capture();const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(draft,null,2)],{type:'application/json'}));a.download='site-design.json';a.click();URL.revokeObjectURL(a.href)};p.querySelector('#upload-design').onchange=async e=>{try{const file=e.target.files[0];if(!file||file.size>50000)throw Error('Invalid file');draft=design(JSON.parse(await file.text()));render();msg(tr('Imported for preview only','تم الاستيراد للمعاينة فقط'))}catch(e){msg(e)}};const h=p.querySelector('#design-history');api('site/history').then(rows=>{h.innerHTML=rows.map(r=>`<div class="section-sort-row"><span>${esc(r.created)} · ${esc(design(JSON.parse(r.snapshot)).site_name)}</span><button data-restore="${r.id}">${tr('Restore','استعادة')}</button></div>`).join('')||tr('No previous settings','لا توجد إعدادات سابقة');h.querySelectorAll('[data-restore]').forEach(b=>b.onclick=async()=>{if(!confirm(tr('Restore saved configuration and profile?','استعادة الإعدادات والهوية المحفوظة؟')))return;try{base=design(await api('site/restore',{id:Number(b.dataset.restore),confirm:true}));draft=structuredClone(base);render();msg(tr('Restored','تمت الاستعادة'))}catch(e){msg(e)}})}).catch(e=>{h.textContent=e.message});preview()}render()}catch(e){msg(e)}}

function profile(site,rows=[]){const get=k=>site[k+'_'+(ar?'ar':'en')]||'';return `<section id="identity" class="identity content-section"><div class="portrait"><div class="portrait-grid"></div><div class="portrait-mark" aria-hidden="true">IX<span>.</span></div><div class="portrait-caption">${tr('THE PERSON BEHIND THE WORK','الشخص وراء الأعمال')}</div></div><div class="identity-copy"><div class="eyebrow">01 / ${tr('PERSONAL IDENTITY','الهوية الشخصية')}</div><h2>${esc(site.name||tr('Meet the creator','تعرّف على صاحب المنصة'))}</h2><p class="role">${esc(get('role'))}</p><p class="bio">${esc(get('bio')||tr('A space for my story, ideas and the work I create.','مساحة لقصتي وأفكاري والأعمال التي أصنعها.'))}</p><div class="identity-details">${['vision','journey'].map(k=>get(k)?`<article><h3>${k==='vision'?tr('My vision','رؤيتي'):tr('My journey','رحلتي')}</h3><p>${esc(get(k))}</p></article>`:'').join('')}</div><div class="actions">${['github','linkedin'].map(k=>site[k]?`<a class="secondary" href="${esc(site[k])}" target="_blank" rel="noopener noreferrer">${k==='github'?'GitHub':'LinkedIn'} ↗</a>`:'').join('')}<a class="primary" href="#contact">${tr('Connect with me','تواصل معي')}</a></div></div>${identityCards(rows)}</section>`}
async function identityEditor(p){try{const site=await api('site');p.innerHTML=`<h2>${tr('Personal identity & design','الهوية الشخصية والتصميم')}</h2><form id="identity-form" class="card"><label>${tr('Display name','الاسم الظاهر')}<input name="name" maxlength="80" value="${esc(site.name)}"></label>${[['role','Professional headline','المسمى المهني'],['bio','My story','قصتي'],['vision','My vision','رؤيتي'],['journey','My journey','رحلتي'],['headline','Hero title','عنوان الرئيسية'],['subline','Hero subtitle','العنوان الثاني'],['welcome','Welcome message','رسالة الترحيب'],['seo_title','Search title (max 120)','عنوان نتائج البحث (120 حرفًا)'],['seo_description','Search description (max 320)','وصف نتائج البحث (320 حرفًا)']].map(([k,en,a])=>`<div class="identity-details">${['ar','en'].map(l=>`<label>${tr(en,a)} · ${l==='ar'?'العربية':'English'}<textarea dir="${l==='ar'?'rtl':'ltr'}" name="${k}_${l}" maxlength="${k==='seo_title'?120:k==='seo_description'?320:5000}">${esc(site[k+'_'+l])}</textarea></label>`).join('')}</div>`).join('')}${['github','linkedin'].map(k=>`<label>${k}<input type="url" name="${k}" value="${esc(site[k])}"></label>`).join('')}<label>${tr('Welcome frequency','تكرار الترحيب')}<select name="welcome_mode">${[['once','Once per tab','مرة لكل تبويب'],['always','Every page visit','كل زيارة'],['off','Disabled','معطل']].map(([v,en,a])=>`<option value="${v}" ${(site.welcome_mode||'once')===v?'selected':''}>${tr(en,a)}</option>`).join('')}</select></label><button class="primary">${tr('Save public identity','حفظ الهوية العامة')}</button></form>`;p.querySelector('form').onsubmit=async e=>{e.preventDefault();if(!confirm(tr('Publish profile settings?','نشر إعدادات الهوية؟')))return;try{const v=await api('site',Object.fromEntries(new FormData(e.target)));applySite(v);msg(tr('Saved','تم الحفظ'))}catch(e){msg(e)}}}catch(e){msg(e)}}
async function historyEditor(id){try{const rows=await api('revisions?id='+encodeURIComponent(id));const el=document.querySelector('#editor');el.innerHTML=`<div class="card"><h3>${tr('Revision history','تاريخ التعديلات')}</h3>${rows.map(x=>`<p>${esc(x.created)} · ${esc(JSON.parse(x.snapshot).title)} <button data-revision="${x.id}">${tr('Restore','استعادة')}</button></p>`).join('')||tr('No earlier versions','لا توجد نسخ سابقة')}</div>`;el.querySelectorAll('[data-revision]').forEach(b=>b.onclick=async()=>{if(!confirm(tr('Restore this version, including its publication status?','استعادة هذه النسخة بما في ذلك حالة النشر؟')))return;try{await api('restore',{revision:Number(b.dataset.revision)});records=await api('records');dashboard();msg(tr('Restored','تمت الاستعادة'))}catch(e){msg(e)}})}catch(e){msg(e)}}
document.querySelector('#lang').textContent=ar?'English':'العربية';document.querySelector('footer span').textContent=tr('Independent technology ecosystem','منظومة تكنولوجية مستقلة');document.querySelector('#theme').setAttribute('aria-label',tr('Change theme','تغيير المظهر'));
try{const initial=design(await api('site'));if(['ar','en'].includes(new URLSearchParams(location.search).get('lang'))){ar=new URLSearchParams(location.search).get('lang')==='ar';localStorage.lang=ar?'ar':'en';document.documentElement.lang=ar?'ar':'en';document.documentElement.dir=ar?'rtl':'ltr'}if(!localStorage.theme)document.body.classList.toggle('light',initial.default_theme==='light');applySite(initial);if(location.pathname==='/admin')await admin();else if(location.pathname==='/projects'){await gallery();welcome(await api('site'))}else if(/^\/(project|showcase)\//.test(location.pathname)){await projectPage();welcome(await api('site'))}else {await home(); await liveShowcases();welcome(await api('site'));applySite(currentDesign);arrangeSite(); if(!matchMedia('(prefers-reduced-motion: reduce)').matches && 'IntersectionObserver' in window){const observer=new IntersectionObserver(entries=>{for(const entry of entries)if(entry.isIntersecting){entry.target.classList.add('visible');observer.unobserve(entry.target)}},{threshold:.08});document.querySelectorAll('.content-section,.contact').forEach(el=>{if(el.getBoundingClientRect().top>innerHeight){el.classList.add('reveal');observer.observe(el)}})}}}catch(e){app.textContent=e.message}

// Floating assistant: public navigation; authenticated AI drafts with explicit approval.
const assistant=document.createElement('aside');assistant.className='assistant';assistant.innerHTML=`<button class="assistant-toggle" aria-expanded="false">✳ ${tr('AXIS AI','أكسيس الذكي')}</button><section class="assistant-panel" hidden><div class="assistant-head"><strong>${tr('AXIS AI','أكسيس الذكي')}</strong><button class="assistant-close" aria-label="${tr('Close','إغلاق')}">×</button></div><p>${tr('Explore the site or sign in to create AI-assisted drafts.','استكشف الموقع أو سجل الدخول لإنشاء مسودات بمساعدة الذكاء الاصطناعي.')}</p><div class="assistant-links"><a href="/#work">${tr('Projects','المشاريع')}</a><a href="/#services">${tr('Services','الخدمات')}</a><a href="/#contact">${tr('Contact','التواصل')}</a></div><form class="assistant-form"><label>${tr('Your request','طلبك')}<textarea name="prompt" required maxlength="2000" placeholder="${tr('Create an article draft…','أنشئ مسودة مقال…')}"></textarea></label><button class="primary">${tr('Ask assistant','اسأل المساعد')}</button></form><p class="assistant-result" role="status"></p><button class="assistant-approve" hidden>${tr('Approve and save draft','وافق واحفظ المسودة')}</button></section>`;document.body.append(assistant);applySite(currentDesign);arrangeSite();const panel=assistant.querySelector('.assistant-panel'),toggle=assistant.querySelector('.assistant-toggle'),result=assistant.querySelector('.assistant-result'),approve=assistant.querySelector('.assistant-approve');let pending=null;function showAssistant(v){panel.hidden=!v;toggle.setAttribute('aria-expanded',String(v));if(v)assistant.querySelector('textarea').focus();else toggle.focus()}toggle.onclick=()=>showAssistant(panel.hidden);assistant.querySelector('.assistant-close').onclick=()=>showAssistant(false);assistant.addEventListener('keydown',e=>{if(e.key==='Escape')showAssistant(false)});assistant.querySelector('form').onsubmit=async e=>{e.preventDefault();pending=null;approve.hidden=true;result.textContent=tr('Preparing…','جارٍ التحضير…');try{const v=await api('ai/draft',{prompt:new FormData(e.target).get('prompt'),language:ar?'ar':'en'});pending=v.id;result.textContent=v.title+'\n'+v.body;approve.hidden=false}catch(e){result.textContent=tr('Sign in and configure the AI provider first, or try again.','سجل الدخول واضبط مزود الذكاء الاصطناعي أولًا، أو أعد المحاولة.') }};approve.onclick=async()=>{if(!pending)return;approve.disabled=true;try{await api('ai/approve',{id:pending});pending=null;approve.hidden=true;result.textContent=tr('Draft saved. Review it in the workspace.','تم حفظ المسودة. راجعها في مساحة العمل.');if(location.pathname==='/admin'){records=await api('records');dashboard()}}catch(e){result.textContent=tr('Could not save draft.','تعذر حفظ المسودة.')}finally{approve.disabled=false}};

async function importStudio(p){p.innerHTML=`<div class="studio-banner"><div class="eyebrow">AXIS / ${tr('PROJECT STUDIO','استوديو المشاريع')}</div><h2>${tr('From source to showcase.','من الملفات إلى تجربة احترافية.')}</h2><p>${tr('Archive source files, optionally sync to a private GitHub repository, then publish an approved project record.','احفظ الملفات الأصلية، وزامنها اختياريًا مع مستودع خاص، ثم انشر سجل المشروع بعد مراجعته.')}</p></div><form class="card" id="import-form"><label>${tr('Project title','عنوان المشروع')}<input name="title" required maxlength="150"></label><div class="import-options"><label class="upload-zone">${tr('01 / Choose entire folder','01 / اختيار فولدر كامل')}<input type="file" name="folder" webkitdirectory multiple></label><label class="upload-zone">${tr('02 / Choose individual files','02 / اختيار ملفات متعددة')}<input type="file" name="individual" multiple></label><div class="upload-zone" id="drop-zone" tabindex="0" role="button">${tr('03 / Drag files or folders here','03 / اسحب الملفات أو الفولدرات هنا')}</div><label class="upload-zone">${tr('04 / Choose ZIP archive','04 / اختيار ملف ZIP')}<input type="file" name="zip" accept=".zip"></label></div><p id="file-summary" role="status"></p><div id="selected-files"></div><button type="button" id="clear-selection">${tr('Clear selection','مسح الاختيار')}</button><label class="sync-choice"><input type="checkbox" name="sync"> ${tr('Sync approved files to configured private GitHub repository','زامن الملفات المعتمدة مع مستودع GitHub الخاص المحدد')}</label><p class="muted">${tr('Maximum 200 files / 5 MB. Hidden files, dependencies and common secret files are excluded. Check the selection for private data before syncing.','الحد 200 ملف / 5 ميجابايت. تُستبعد الملفات المخفية والتبعيات وملفات الأسرار الشائعة. راجع البيانات الخاصة قبل المزامنة.')}</p><button class="primary">${tr('Import as private draft','استيراد كمسودة خاصة')}</button></form><div id="import-list"></div>`;let files=[],busy=false;const f=p.querySelector('form'),summary=p.querySelector('#file-summary'),list=p.querySelector('#selected-files');const pathOf=x=>x.relativePath||x.webkitRelativePath||x.name;const allowed=x=>!pathOf(x).split('/').some(y=>y.startsWith('.')||/^(node_modules|venv|__pycache__|credentials|secrets)$/i.test(y))&&!/(?:\.pem|\.key|\.p12|\.sqlite3?-wal|\.sqlite3?-shm|\.db-wal|\.db-shm|\.sqlite3?-journal|\.db-journal|\.env|\.exe|\.dll|\.zip)$/i.test(x.name)&&!/password|credential|secret|token/i.test(x.name);function renderSelection(skipped=0){summary.textContent=tr('Selected: ','المحدد: ')+files.length+' · '+(files.reduce((n,x)=>n+x.size,0)/1048576).toFixed(2)+' MB · '+tr('Skipped: ','المستبعد: ')+skipped;list.replaceChildren();files.forEach((x,i)=>{const row=document.createElement('div'),btn=document.createElement('button');row.className='file-row';row.append(document.createTextNode(pathOf(x)));btn.type='button';btn.textContent=tr('Remove','إزالة');btn.onclick=()=>{files.splice(i,1);renderSelection()};row.append(btn);list.append(row)});}function add(all){const map=new Map(files.map(x=>[pathOf(x),x]));let skipped=0;for(const x of all){if(!allowed(x)){skipped++;continue}if(map.has(pathOf(x))){skipped++;continue}map.set(pathOf(x),x)}files=[...map.values()];renderSelection(skipped)};for(const name of ['folder','individual'])f.elements.namedItem(name).onchange=e=>{add([...e.target.files]);e.target.value=''};p.querySelector('#clear-selection').onclick=()=>{files=[];renderSelection()};const drop=p.querySelector('#drop-zone');drop.onclick=()=>f.elements.namedItem('individual').click();drop.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();drop.click()}};drop.ondragover=e=>{e.preventDefault();drop.classList.add('dragging')};drop.ondragleave=()=>drop.classList.remove('dragging');async function walk(entry,prefix=''){if(entry.isFile)return [await new Promise((resolve,reject)=>entry.file(file=>{file.relativePath=prefix+file.name;resolve(file)},reject))];if(!entry.isDirectory)return [];const reader=entry.createReader(),out=[];while(true){const batch=await new Promise((resolve,reject)=>reader.readEntries(resolve,reject));if(!batch.length)break;for(const item of batch){out.push(...await walk(item,prefix+entry.name+'/'));if(out.length>1000)throw Error(tr('Too many files','ملفات كثيرة جدًا'))}}return out}drop.ondrop=async e=>{e.preventDefault();drop.classList.remove('dragging');if(busy)return;const entries=[...e.dataTransfer.items].map(i=>i.webkitGetAsEntry?.()).filter(Boolean),fallback=[...e.dataTransfer.files];busy=true;try{const all=[];if(entries.length){for(const entry of entries)all.push(...await walk(entry))}else all.push(...fallback);add(all)}catch(e){summary.textContent=e.message}finally{busy=false}};f.elements.namedItem('zip').onchange=async e=>{const file=e.target.files[0];e.target.value='';if(!file||busy)return;busy=true;try{if(file.size>5242880)throw Error(tr('ZIP exceeds 5 MB','ملف ZIP يتجاوز 5 ميجابايت'));const bytes=new Uint8Array(await file.arrayBuffer());let binary='';for(let i=0;i<bytes.length;i+=8192)binary+=String.fromCharCode(...bytes.subarray(i,i+8192));const result=await api('import/zip',{data:btoa(binary)});add(result.files.map(x=>{const file=new File([Uint8Array.from(atob(x.data),c=>c.charCodeAt(0))],x.path.split('/').at(-1));file.relativePath=x.path;return file}));}catch(e){summary.textContent=e.message}finally{busy=false}};f.onsubmit=async e=>{e.preventDefault();const submit=f.querySelector('button[type=submit]')||f.querySelector('.primary');if(busy)return;if(!files.length||files.length>200||files.reduce((n,x)=>n+x.size,0)>5242880){summary.textContent=tr('Selection exceeds limits or is empty.','الملفات فارغة أو تتجاوز الحد.');return;}if(f.elements.namedItem("sync").checked&&!confirm(tr('Send selected files to the configured private GitHub repository?','إرسال الملفات المحددة إلى مستودع GitHub الخاص؟')))return;submit.disabled=true;try{const payload=[];for(const x of files){const bytes=new Uint8Array(await x.arrayBuffer());let binary='';for(let i=0;i<bytes.length;i+=8192)binary+=String.fromCharCode(...bytes.subarray(i,i+8192));payload.push({path:pathOf(x),data:btoa(binary)});}const v=await api('import',{title:f.elements.namedItem("title").value,files:payload,sync:f.elements.namedItem("sync").checked});summary.textContent=tr('Private project saved. ','تم حفظ المشروع الخاص. ')+(v.commit?'GitHub: '+v.commit.slice(0,10):v.warning?tr('Sync failed: ','تعذرت المزامنة: ')+v.warning:'');records=await api('records');await loadImports();}catch(e){summary.textContent=e.message}finally{submit.disabled=false}};async function loadImports(){const rows=await api('imports');p.querySelector('#import-list').innerHTML=`<h3>${tr('Import history','سجل الاستيراد')}</h3>${rows.map(r=>`<article class="card"><strong>${esc(records.find(x=>x.id===r.id)?.title||r.id)}</strong><p>${esc(r.created)} · ${r.commit_sha?tr('Synced','تمت المزامنة'):tr('Local archive','أرشيف محلي')}</p></article>`).join('')}`}try{await loadImports()}catch(e){msg(e)}}

function showcaseCards(items){return items.map(x=>`<article class="card live-card"><div class="eyebrow">${esc(x.kind==='activity'?tr('ACTIVITY','نشاط'):x.kind==='powerbi'?'POWER BI':x.kind==='tableau'?'TABLEAU':tr('LIVE PROJECT','مشروع حي'))}</div><h3>${esc(x[ar?'title_ar':'title_en'])}</h3><p>${esc(x[ar?'body_ar':'body_en'])}</p>${x.kind==='activity'&&x.count!==null?`<strong class="activity-number">${esc(x.count.toLocaleString(ar?'ar':'en'))}</strong><p>${esc(x[ar?'metric_ar':'metric_en'])}</p><small>${x.source==='github'?'GitHub':x.source==='codeforces'?'Codeforces':tr('Owner-reported','بيانات مدخلة بواسطة المالك')} · ${tr('updated','تحديث')} ${esc(new Date(x.updated).toLocaleDateString(ar?'ar':'en'))}</small>`:''}${['powerbi','tableau'].includes(x.kind)?`<button class="primary load-report" data-url="${esc(x.url)}">${tr('Explore live report','استكشف التقرير الحي')}</button><div class="report-slot"></div>`:''}<a class="secondary" target="_blank" rel="noopener noreferrer" href="${esc(x.url)}">${tr('Open source','فتح المصدر')} ↗</a><div class="record-actions"><a class="secondary" href="/showcase/${esc(x.id)}?lang=${ar?'ar':'en'}">${tr('Open showcase','افتح العرض')}</a><button data-share-showcase="${esc(x.id)}">${tr('Share','مشاركة')}</button></div></article>`).join('')}
function bindReports(section){section.querySelectorAll('.load-report').forEach(b=>b.onclick=()=>{const slot=b.nextElementSibling;const frame=document.createElement('iframe');frame.src=b.dataset.url;frame.title=tr('Interactive report','تقرير تفاعلي');frame.loading='lazy';frame.referrerPolicy='no-referrer';frame.setAttribute('allowfullscreen','');slot.replaceChildren(frame);b.hidden=true;});}
async function liveShowcases(){const rows=await api('showcases/public');const section=document.createElement('section');section.className='content-section live-section';section.id='live';section.innerHTML=`<div class="section-head"><div><div class="eyebrow">AXIS / ${tr('LIVE EXPERIENCE','تجربة حية')}</div><h2>${tr('Explore my work.','استكشف أعمالي.')}</h2></div></div><div class="live-grid">${showcaseCards(rows.filter(x=>x.kind!=='activity'))||`<p class="muted">${tr('Live projects will appear when published.','ستظهر المشاريع الحية بعد نشرها.')}</p>`}</div><div class="section-head activity-head"><div><div class="eyebrow">AXIS / ${tr('GROWTH','النمو')}</div><h2>${tr('Learning in motion.','رحلة تعلم مستمرة.')}</h2></div></div><div class="grid">${showcaseCards(rows.filter(x=>x.kind==='activity'))||`<p class="muted">${tr('Activity will appear when published.','ستظهر الأنشطة بعد نشرها.')}</p>`}</div>`;document.querySelector('#contact').before(section);bindReports(section);}
async function showcaseEditor(p){try{const rows=await api('showcases');function render(x={}){p.innerHTML=`<div class="studio-banner"><div class="eyebrow">AXIS / SHOWCASE</div><h2>${tr('Live work & learning','الأعمال الحية والتعلم')}</h2><p>${tr('Publish external reports, deployed apps and owner-reported activity.','انشر التقارير والتطبيقات الخارجية والأنشطة المسجلة بواسطتك.')}</p></div><form class="card" id="showcase-form"><label>${tr('Type','النوع')}<select name="kind">${[['powerbi','Power BI'],['tableau','Tableau Public'],['link',tr('Deployed app / external link','تطبيق منشور / رابط')],['activity',tr('Learning activity','نشاط تعليمي')]].map(([v,t])=>`<option value="${v}" ${x.kind===v?'selected':''}>${t}</option>`).join('')}</select></label>${['ar','en'].map(l=>`<label>${tr('Title','العنوان')} / ${l}<input name="title_${l}" maxlength="150" required value="${esc(x['title_'+l])}"></label><label>${tr('Description','الوصف')} / ${l}<textarea name="body_${l}" maxlength="4000">${esc(x['body_'+l])}</textarea></label>`).join('')}<label>${tr('Public URL','الرابط العام')}<input type="url" name="url" required value="${esc(x.url)}"></label><label>${tr('Linked project (optional)','المشروع المرتبط (اختياري)')}<select name="project_id"><option value="">${tr('Independent showcase','عرض مستقل')}</option>${records.filter(r=>r.kind==='project'&&r.status!=='deleted').map(r=>`<option value="${esc(r.id)}" ${x.project_id===r.id?'selected':''}>${esc(localized(r,'title'))}</option>`).join('')}</select></label><small>${tr('Linked showcases are public only when their project is published.','العرض المرتبط لا يظهر إلا إذا كان المشروع منشورًا.')}</small><div id="metric-fields"><label>${tr('Count (optional, manually recorded)','العدد (اختياري، مدخل يدويًا)')}<input type="number" min="0" step="1" name="count" value="${esc(x.count)}"></label>${['ar','en'].map(l=>`<label>${tr('Metric name','اسم المؤشر')} / ${l}<input name="metric_${l}" value="${esc(x['metric_'+l])}"></label>`).join('')}</div><label class="sync-choice"><input name="published" type="checkbox" ${x.published?'checked':''}>${tr('Publish publicly','نشر للعامة')}</label><button class="primary">${tr('Save','حفظ')}</button></form><button id="new-showcase">${tr('New entry','عنصر جديد')}</button><div class="grid">${rows.map(r=>`<article class="card"><h3>${esc(r[ar?'title_ar':'title_en'])}</h3><p>${r.deleted?tr('Trash','سلة المحذوفات'):r.published?tr('Published','منشور'):tr('Private draft','مسودة خاصة')}</p>${r.deleted?'':`<button data-showcase="${esc(r.id)}">${tr('Edit','تعديل')}</button>`}${showcaseAdminActions(r)}${!r.deleted&&r.kind==='activity'?`<button data-refresh="${esc(r.id)}">${tr('Refresh from source','تحديث من المصدر')}</button>`:''}</article>`).join('')}</div>`;const f=p.querySelector('form');const toggle=()=>p.querySelector('#metric-fields').hidden=f.elements.kind.value!=='activity';f.elements.kind.onchange=toggle;toggle();f.onsubmit=async e=>{e.preventDefault();const v=Object.fromEntries(new FormData(f));v.published=f.elements.published.checked;if(v.published&&!confirm(tr('Make this link and its metadata public? Confirm that no confidential data is exposed.','نشر الرابط وبياناته للعامة؟ تأكد من عدم وجود بيانات سرية.')))return;try{await api('showcases',{...v,id:x.id});await showcaseEditor(p);msg(tr('Saved','تم الحفظ'))}catch(e){msg(e)}};p.querySelectorAll('[data-refresh]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{await api('showcases/refresh',{id:b.dataset.refresh});await showcaseEditor(p);msg(tr('Refreshed','تم التحديث'))}catch(e){msg(e);b.disabled=false}});p.querySelectorAll('[data-showcase-action]').forEach(b=>b.onclick=async()=>{if(!confirm(tr('Confirm this change?','تأكيد تغيير الحالة؟')))return;try{await api('showcases/visibility',{id:b.dataset.showcaseId,action:b.dataset.showcaseAction,confirm:true});await showcaseEditor(p);announce(tr('Updated','تم التحديث'))}catch(e){announce(e.message)}});p.querySelector('#new-showcase').onclick=()=>render();p.querySelectorAll('[data-showcase]').forEach(b=>b.onclick=()=>render(rows.find(r=>r.id===b.dataset.showcase)));}render()}catch(e){msg(e)}}

function shareUrl(id,type='project'){const u=new URL(id?'/'+type+'/'+id:'/',location.origin);u.searchParams.set('lang',ar?'ar':'en');return u.href}
async function copyLink(url){try{await navigator.clipboard.writeText(url);announce(tr('Link copied','تم نسخ الرابط'))}catch{window.prompt(tr('Copy this link','انسخ هذا الرابط'),url)}}
function announce(text){let n=document.querySelector('#notice');if(!n){n=document.createElement('div');n.id='notice';n.className='notice';n.setAttribute('role','status');document.body.append(n)}n.textContent=text;clearTimeout(n.timer);n.timer=setTimeout(()=>n.remove(),3500)}
function projectActions(x){return `<div class="record-actions"><a class="primary" href="/project/${esc(x.id)}?lang=${ar?'ar':'en'}">${tr('Explore project','استكشف المشروع')} ↗</a><button type="button" data-share="${esc(x.id)}">${tr('Share','مشاركة')}</button></div>`}
function recordActions(x){const a=(v,e,b)=>`<button type="button" data-record-action="${v}" data-record-id="${esc(x.id)}">${tr(e,b)}</button>`;return `<div class="record-actions">${x.status==='deleted'?a('restore','Restore privately','استعادة كمسودة'): (x.status==='published'?a('hide','Hide from visitors','إخفاء عن الزوار')+(x.kind==='project'?`<button data-share="${esc(x.id)}">${tr('Copy link','نسخ الرابط')}</button>`:''):['project','skill','achievement','certification','education','career','page','product','service','article','experience'].includes(x.kind)?a('publish','Publish','نشر'):'')+a('trash','Move to trash','نقل لسلة المحذوفات')}</div>`}
function bindRecordActions(){document.querySelectorAll('[data-record-action]').forEach(b=>b.onclick=async()=>{if(!confirm(tr('Confirm this change?','تأكيد تغيير الحالة؟')))return;try{await api('records/visibility',{id:b.dataset.recordId,action:b.dataset.recordAction,confirm:true});records=await api('records');dashboard();announce(tr('Updated','تم التحديث'))}catch(e){announce(e.message)}})}
function identityCards(rows){const groups=['skill','achievement','certification','education','career'];return `<div class="identity-catalog">${groups.map(k=>{const items=rows.filter(x=>x.kind===k);return items.length?`<div class="identity-group"><h3>${label(k)}</h3><div class="identity-grid">${items.map(x=>`<article class="identity-chip"><span class="identity-icon">${iconSvg(x.icon||pickIcon(localized(x,'title'),k))}</span><div><strong>${esc(localized(x,'title'))}</strong><p>${esc(localized(x,'body'))}</p></div></article>`).join('')}</div></div>`:''}).join('')}</div>`}
function publicPath(path,hash=''){return path+'?lang='+(ar?'ar':'en')+hash}
function projectNavigationMarkup(n){if(!n)return '';const card=x=>`<article class="card gallery-card"><span class="identity-icon">${iconSvg(x.icon||pickIcon(localized(x,'title'),'project'))}</span><h3>${esc(localized(x,'title'))}</h3><p>${esc(localized(x,'body'))}</p>${projectActions(x)}</article>`;const step=(x,prev)=>x?`<a class="project-step" href="${publicPath('/project/'+esc(x.id))}"><span class="eyebrow">${prev?tr('← Previous project','المشروع السابق →'):tr('Next project →','← المشروع التالي')}</span><strong>${esc(localized(x,'title'))}</strong></a>`:'';return `<section class="project-discovery"><div class="section-head"><div><div class="eyebrow">${tr('KEEP EXPLORING','واصل الاستكشاف')}</div><h2>${tr('More of my work.','المزيد من أعمالي.')}</h2></div><a class="secondary" href="${publicPath('/projects')}">${tr('Explore all projects','استعرض كل المشاريع')} (${n.total}) ↗</a></div>${n.previous||n.next?`<div class="project-steps">${step(n.previous,true)}${step(n.next,false)}</div>`:''}${n.related.length?`<h3>${tr('Related projects','مشاريع مشابهة')}</h3><div class="grid">${n.related.map(card).join('')}</div>`:''}${n.more.length?`<h3>${tr('Discover other projects','اكتشف مشاريع أخرى')}</h3><div class="grid">${n.more.map(card).join('')}</div>`:''}${n.total===1?`<p>${tr('More projects will appear when published.','ستظهر أعمال أخرى عند نشرها.')}</p>`:''}</section>`}
function creatorLinks(site){const hidden=currentDesign.hidden_sections||[];return `<section class="creator-links card"><span class="identity-icon">${iconSvg('work')}</span><div><div class="eyebrow">${tr('BEHIND THE PROJECT','وراء المشروع')}</div><h2>${esc(site.name||tr('Meet the creator','تعرّف على صاحب المنصة'))}</h2><p>${esc(site[ar?'role_ar':'role_en']||'')}</p></div><div class="actions">${hidden.includes('identity')?'':`<a class="secondary" href="${publicPath('/','#identity')}">${tr('About me','تعرّف عليّ')}</a>`}<a class="secondary" href="${publicPath('/')}">${tr('Home','الرئيسية')}</a>${hidden.includes('contact')?'':`<a class="primary" href="${publicPath('/','#contact')}">${tr('Contact me','تواصل معي')}</a>`}</div></section>`}
async function projectPage(){try{const isShowcase=location.pathname.startsWith('/showcase/');const [x,site]=await Promise.all([api('public/'+(isShowcase?'showcase':'record')+'/'+location.pathname.split('/').at(-1)),api('site')]);if(isShowcase){app.innerHTML=`<section class="project-detail"><a class="secondary" href="${publicPath('/projects')}">← ${tr('All projects','كل المشاريع')}</a>${x.project_id?`<a class="secondary" href="${publicPath('/project/'+esc(x.project_id))}">${tr('Back to project','العودة للمشروع')}</a>`:''}<div class="eyebrow">${tr('LIVE SHOWCASE','تجربة حية')}</div>${showcaseCards([x])}<button data-share-showcase="${esc(x.id)}">${tr('Share experience','مشاركة التجربة')}</button></section>${projectNavigationMarkup(x.navigation)}${creatorLinks(site)}`;bindReports(app);return}app.innerHTML=`<section class="project-detail"><a class="secondary" href="/projects?lang=${ar?'ar':'en'}">← ${tr('All projects','كل المشاريع')}</a><div class="eyebrow">${tr('PROJECT / SHOWCASE','المشروع / العرض')}</div><span class="identity-icon">${iconSvg(x.icon||pickIcon(x.title,x.kind))}</span><h1>${esc(localized(x,'title'))}</h1>${catalogChips(x,true)}<p class="project-description">${esc(localized(x,'body'))}</p><button class="primary" data-share="${esc(x.id)}">${tr('Share project','مشاركة المشروع')} ↗</button>${x.data_experience?`<div id="data-experience">${dataMarkup(x.data_experience)}</div>`:''}${x.showcases?.length?`<div class="linked-showcases"><h2>${tr('Live experiences','التجارب الحية')}</h2>${showcaseCards(x.showcases)}</div>`:''}</section>${projectNavigationMarkup(x.navigation)}${creatorLinks(site)}`;bindReports(app);if(x.data_experience)bindData(app.querySelector('#data-experience'),x.data_experience)}catch{app.innerHTML=`<section class="card"><h1>${tr('Project unavailable','المشروع غير متاح')}</h1><p>${tr('This project may be private or removed.','ربما أصبح المشروع خاصًا أو تمت إزالته.')}</p><a class="primary" href="${publicPath('/projects')}">${tr('Explore all projects','استعرض كل المشاريع')}</a> <a href="${publicPath('/')}">${tr('Back home','العودة للرئيسية')}</a></section>`}}
function welcome(site){const mode=site.welcome_mode||'once',key='welcome-'+(ar?'ar':'en');if(mode==='off'||(mode==='once'&&sessionStorage.getItem(key)))return;sessionStorage.setItem(key,'1');const n=document.createElement('aside');n.className='welcome-card';n.setAttribute('role','status');n.innerHTML=`<span class="welcome-symbol">✦</span><div><strong>${tr('Welcome to ','مرحبًا بك في ')}${esc(ar?(site.site_name_ar||site.site_name||'IBRAXIS'):(site.site_name||'IBRAXIS'))}</strong><p>${esc(site[ar?'welcome_ar':'welcome_en']||tr('Explore my work, ideas and journey. Glad you are here.','استكشف أعمالي وأفكاري ورحلتي. سعيد بزيارتك.'))}</p></div><button aria-label="${tr('Dismiss','إغلاق')}">×</button>`;document.body.append(n);n.querySelector('button').onclick=()=>n.remove();setTimeout(()=>n.remove(),12000)}
document.addEventListener('click',e=>{const b=e.target.closest('[data-share]');if(b)copyLink(shareUrl(b.dataset.share));const c=e.target.closest('[data-share-showcase]');if(c)copyLink(shareUrl(c.dataset.shareShowcase,'showcase'))});const share=document.createElement('button');share.textContent=tr('Share site','مشاركة الموقع');share.onclick=()=>copyLink(shareUrl());document.querySelector('nav').append(share);const galleryLink=document.querySelector('nav a');galleryLink.href='/projects?lang='+(ar?'ar':'en');galleryLink.textContent=tr('All projects','كل المشاريع');document.querySelectorAll('header .logo,footer .logo').forEach(a=>a.href=publicPath('/'));document.querySelectorAll('nav a,.assistant-links a').forEach(a=>{const u=new URL(a.href,location.origin);if(u.origin===location.origin){u.searchParams.set('lang',ar?'ar':'en');if(a.closest('.assistant-links')&&u.hash==='#work'){u.pathname='/projects';u.hash=''}a.href=u.pathname+u.search+u.hash}});

function showcaseAdminActions(x){const a=(v,en,a)=>`<button type="button" data-showcase-action="${v}" data-showcase-id="${esc(x.id)}">${tr(en,a)}</button>`;return `<div class="record-actions">${x.deleted?a('restore','Restore privately','استعادة كمسودة'):(x.published?a('hide','Hide','إخفاء')+`<button data-share-showcase="${esc(x.id)}">${tr('Copy link','نسخ الرابط')}</button>`:'')+a('trash','Move to trash','نقل لسلة المحذوفات')}</div>`}

async function gallery(){
 const rows=(await api('public')).filter(x=>x.kind==='project');
 const live=(await api('showcases/public')).filter(x=>x.kind!=='activity');
 const hasLive=new Set(live.map(x=>x.project_id).filter(Boolean));
 const siteName=ar?(currentDesign.site_name_ar||currentDesign.site_name):currentDesign.site_name;
 document.title=tr('All projects','كل المشاريع')+' — '+siteName;
 app.innerHTML=`<section class="gallery-intro"><div class="eyebrow">${esc(siteName)} / ${tr('PROJECT ATLAS','أطلس المشاريع')}</div><h1>${tr('Ideas into reality.','من الأفكار إلى الواقع.')}</h1><p>${tr('Discover every published project and explore the available live experiences.','اكتشف جميع المشاريع المنشورة واستكشف التجارب الحية المتاحة.')}</p><div class="actions"><a class="secondary" href="/?lang=${ar?'ar':'en'}">${tr('Back home','العودة للرئيسية')}</a><button id="share-gallery">${tr('Share gallery','مشاركة المعرض')}</button></div></section><section class="gallery-tools card"><label>${tr('Search projects','ابحث عن مشروع')}<input id="gallery-search" type="search" placeholder="${tr('Project name, technology, description…','اسم المشروع أو التقنية أو الوصف…')}"></label><label>${tr('Show','عرض')}<select id="gallery-filter"><option value="all">${tr('All projects','كل المشاريع')}</option><option value="live">${tr('With live experiences','مع تجارب حية')}</option></select></label><label>${tr('Sort','الترتيب')}<select id="gallery-sort"><option value="recent">${tr('Newest first','الأحدث أولًا')}</option><option value="name">${tr('By name','حسب الاسم')}</option><option value="featured">${tr('Featured first','المميزة أولًا')}</option></select></label><label>${tr('Field','المجال')}<select id="gallery-domain"></select></label><label>${tr('Technology','التقنية')}<select id="gallery-tech"></select></label><label>${tr('Layout','طريقة العرض')}<select id="gallery-view"><option value="grid">${tr('Cards','بطاقات')}</option><option value="list">${tr('List','قائمة')}</option></select></label></section><div id="atlas-tree" class="atlas-tree"></div><p id="gallery-count" role="status"></p><div id="gallery-results" class="grid gallery-grid"></div>`;
 const search=app.querySelector('#gallery-search'),filter=app.querySelector('#gallery-filter'),sort=app.querySelector('#gallery-sort'),domain=app.querySelector('#gallery-domain'),tech=app.querySelector('#gallery-tech'),view=app.querySelector('#gallery-view');
 const keys=(rows,k)=>[...new Set(rows.flatMap(x=>x.classification?.[k]||[]))].sort((a,b)=>cl(a).localeCompare(cl(b),ar?'ar':'en'));
 const fill=(el,vals,chosen)=>{el.innerHTML=`<option value="">${tr('All','الكل')}</option>`+vals.map(k=>`<option value="${esc(k)}">${esc(cl(k))}</option>`).join('');el.value=vals.includes(chosen)?chosen:''};
 const params=new URLSearchParams(location.search);fill(domain,keys(rows,'domains'),params.get('domain'));const refreshTech=chosen=>fill(tech,keys(rows.filter(x=>!domain.value||x.classification?.domains.includes(domain.value)),'technologies'),chosen);refreshTech(params.get('tech'));
 app.querySelector('#atlas-tree').innerHTML=keys(rows,'domains').map(d=>{const subset=rows.filter(x=>x.classification?.domains.includes(d));return `<details class="card"><summary>${esc(cl(d))} <small>${subset.length}</small></summary><div class="atlas-branches"><a href="${atlasUrl(d,'')}">${tr('All in this field','كل مشاريع المجال')}</a>${keys(subset,'technologies').map(t=>`<a href="${atlasUrl(d,t)}">${esc(cl(t))} <small>${subset.filter(x=>x.classification.technologies.includes(t)).length}</small></a>`).join('')}</div></details>`}).join('');
 function render(){let items=rows.filter(x=>(filter.value!=='live'||hasLive.has(x.id))&&(!domain.value||x.classification?.domains.includes(domain.value))&&(!tech.value||x.classification?.technologies.includes(tech.value))&&matches(x,search.value));if(sort.value==='name')items.sort((a,b)=>localized(a,'title').localeCompare(localized(b,'title'),ar?'ar':'en'));if(sort.value==='featured')items.sort((a,b)=>Number(b.classification?.featured)-Number(a.classification?.featured));app.querySelector('#gallery-count').textContent=items.length+' / '+rows.length+' '+tr('published projects','مشروع منشور');const output=app.querySelector('#gallery-results');output.classList.toggle('atlas-list',view.value==='list');output.innerHTML=items.map(x=>`<article class="card gallery-card"><div class="gallery-card-top"><span class="identity-icon">${iconSvg(x.icon||pickIcon(localized(x,'title'),'project'))}</span>${hasLive.has(x.id)?`<span class="eyebrow">${tr('LIVE EXPERIENCE','تجربة حية')}</span>`:''}</div><h3>${esc(localized(x,'title'))}</h3>${catalogChips(x,false)}<p>${esc((localized(x,'body')||'').slice(0,280))}</p>${projectActions(x)}</article>`).join('')||`<p class="empty">${tr('No matching published projects.','لا توجد مشاريع منشورة مطابقة.')}</p>`;}
 search.oninput=filter.onchange=sort.onchange=tech.onchange=view.onchange=render;domain.onchange=()=>{refreshTech('');render()};app.querySelector('#share-gallery').onclick=()=>copyLink(new URL(atlasUrl(domain.value,tech.value),location.origin).href);render();
}

function iconLabel(k){const labels={code:["Programming","البرمجة"],data:["Data analysis","تحليل البيانات"],ai:["Artificial intelligence","الذكاء الاصطناعي"],web:["Web","الويب"],database:["Databases","قواعد البيانات"],design:["Design","التصميم"],award:["Achievement","إنجاز"],book:["Education","التعليم"],work:["Career","المسار المهني"],cloud:["Cloud","الحوسبة السحابية"],shield:["Security","الأمن"],star:["General","عام"]};return tr(...(labels[k]||[k,k]))}

function cl(k){return catalogLabel(k,ar?'ar':'en')}
function atlasUrl(d,t){const p=new URLSearchParams({lang:ar?'ar':'en'});if(d)p.set('domain',d);if(t)p.set('tech',t);return '/projects?'+p.toString()}
function catalogChips(x,links){const c=x.classification;if(!c)return '';return `<div class="catalog-chips">${[...(c.domains||[]),...(c.technologies||[]),...(c.tags||[])].map(k=>links&&((c.domains||[]).includes(k)||(c.technologies||[]).includes(k))?`<a href="${atlasUrl(c.domains.includes(k)?k:'',c.technologies.includes(k)?k:'')}">${esc(cl(k))}</a>`:`<span>${esc(cl(k))}</span>`).join('')}</div>`}
function catalogEditor(x){const c=x.classification||{};return `<fieldset class="catalog-edit"><legend>${tr('Classification & discovery','التصنيف والفهرسة')}</legend>${catalogChips(x,false)}<label>${tr('Mode','النمط')}<select name="cat_mode"><option value="auto">${tr('Automatic from project evidence','تلقائي من أدلة المشروع')}</option><option value="manual" ${c.mode==='manual'?'selected':''}>${tr('Manual / custom','يدوي / مخصص')}</option></select></label><label>${tr('Fields (comma separated; manual mode)','المجالات (مفصولة بفاصلة إنجليزية؛ الوضع اليدوي)')}<input name="cat_domains" value="${esc((c.domains||[]).join(', '))}" list="field-options"></label><datalist id="field-options">${domains.map(x=>`<option value="${x[0]}">${esc(cl(x[0]))}</option>`).join('')}</datalist><label>${tr('Technologies (comma separated; manual mode)','التقنيات (مفصولة بفاصلة إنجليزية؛ الوضع اليدوي)')}<input name="cat_tech" value="${esc((c.technologies||[]).join(', '))}" list="tech-options"></label><datalist id="tech-options">${taxonomy.map(x=>`<option value="${x[0]}">${esc(cl(x[0]))}</option>`).join('')}</datalist><label>${tr('Tags (comma separated)','الوسوم (مفصولة بفاصلة إنجليزية)')}<input name="cat_tags" value="${esc((c.tags||[]).join(', '))}"></label><label><input type="checkbox" name="cat_featured" ${c.featured?'checked':''}> ${tr('Featured','مميز')}</label></fieldset>`}
function mountSearch(){const b=document.createElement('button');b.type='button';b.textContent=tr('Search ⌘K','بحث ⌘K');document.querySelector('nav').prepend(b);const dialog=document.createElement('dialog');dialog.className='global-search';dialog.innerHTML=`<div class="search-top"><h2>${tr('Discover','استكشف')}</h2><button type="button" aria-label="${tr('Close','إغلاق')}">×</button></div><input type="search" placeholder="${tr('Search titles, tools, tags…','ابحث في العناوين والتقنيات والوسوم…')}"><div class="search-results" aria-live="polite"></div>`;document.body.append(dialog);const input=dialog.querySelector('input'),out=dialog.querySelector('.search-results');let rows=[];function render(){const q=input.value;out.innerHTML=rows.filter(x=>matches(x,q)).slice(0,60).map(x=>`<article class="search-hit"><small>${esc(label(x.kind))}</small><a href="${x.kind==='project'?publicPath('/project/'+x.id):publicPath('/', '#'+({skill:'identity',achievement:'identity',certification:'identity',education:'identity',career:'identity',page:'about',article:'insights',product:'products',service:'services',experience:'experiences',brand:'identity'}[x.kind]||'identity'))}">${esc(localized(x,'title'))}</a>${catalogChips(x,false)}</article>`).join('')||`<p>${tr('No results','لا توجد نتائج')}</p>`}const open=async()=>{if(dialog.open)return;dialog.showModal();input.focus();try{rows=await api('public');render()}catch{out.textContent=tr('Search unavailable','البحث غير متاح')}};b.onclick=open;dialog.querySelector('button').onclick=()=>dialog.close();input.oninput=render;document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();open()}})}
mountSearch();

function dataMarkup(d){return `<section class="card data-experience"><div class="eyebrow">${tr('INTERACTIVE DATA EXPERIENCE','تجربة بيانات تفاعلية')}</div><h2>${esc(d.metric||tr('Row count','عدد السجلات'))} / ${esc(d.group)}</h2><p>${tr('Input rows','السجلات الأصلية')}: ${d.rowCount} · ${tr('Excluded rows','السجلات المستبعدة')}: ${d.excluded}</p><label>${tr('Filter groups','فلترة المجموعات')}<input type="search" class="data-filter"></label><label>${tr('Sort groups','ترتيب المجموعات')}<select class="data-sort"><option value="high">${tr('Highest first','الأعلى أولًا')}</option><option value="low">${tr('Lowest first','الأقل أولًا')}</option><option value="name">${tr('By name','حسب الاسم')}</option></select></label><div class="data-chart" role="status"></div></section>`}
function bindData(el,d){if(!el)return;const f=el.querySelector('.data-filter'),s=el.querySelector('.data-sort'),o=el.querySelector('.data-chart');const render=()=>{const rows=d.groups.filter(x=>x.label.toLowerCase().includes(f.value.toLowerCase())).sort((a,b)=>s.value==='name'?a.label.localeCompare(b.label):s.value==='low'?a.value-b.value:b.value-a.value);const max=Math.max(1,...rows.map(x=>Math.abs(x.value)));o.innerHTML=rows.map(x=>`<div class="data-bar"><span>${esc(x.label)}</span><meter min="0" max="${max}" value="${Math.abs(x.value)}"></meter><strong>${esc(x.value.toLocaleString(ar?'ar':'en',{maximumFractionDigits:3}))}</strong></div>`).join('')||tr('No matching groups','لا توجد مجموعات مطابقة')};f.oninput=s.onchange=render;render()}
async function dataBuilder(id){const el=document.querySelector('#editor');try{const info=await api('data-experience?id='+id);el.innerHTML=`<section class="card"><h2>${tr('CSV experience builder','منشئ تجربة البيانات')}</h2><p>${tr('Only approved aggregate values and group labels are public. Never publish confidential labels or data.','تظهر فقط القيم المجمعة وأسماء المجموعات بعد الموافقة. لا تنشر بيانات أو تسميات سرية.')}</p><label>${tr('Imported CSV','ملف CSV المستورد')}<select id="data-file"><option value="">${tr('Select a file','اختر ملفًا')}</option>${info.files.map(f=>`<option value="${esc(f.path)}">${esc(f.path)}</option>`).join('')}</select></label><div id="data-cols"></div><div id="data-preview"></div><button id="data-hide">${tr('Hide experience','إخفاء التجربة')}</button><p id="data-msg" role="status"></p></section>`;const file=el.querySelector('#data-file'),cols=el.querySelector('#data-cols'),preview=el.querySelector('#data-preview'),msg=el.querySelector('#data-msg');function show(d){preview.innerHTML=dataMarkup(d)+`<button class="primary" id="data-publish">${tr('Approve aggregate publication','اعتماد نشر البيانات المجمعة')}</button>`;bindData(preview,d);preview.querySelector('#data-publish').onclick=async()=>{if(confirm(tr('Publish these aggregate values and labels to visitors?','هل توافق على نشر القيم المجمعة والتسميات للزوار؟'))){try{await api('data-experience',{id,action:'publish',confirm:true});msg.textContent=tr('Approved; visible when project is published','تم الاعتماد؛ تظهر عند نشر المشروع')}catch(e){msg.textContent=e.message}}}}if(info.saved)show(info.saved);file.onchange=async()=>{try{cols.innerHTML='';if(!file.value)return;const {headers}=await api('data-experience',{id,action:'columns',path:file.value});const opts=headers.map((x,i)=>`<option value="${i}">${esc(x)}</option>`).join('');cols.innerHTML=`<label>${tr('Group by','التجميع حسب')}<select id="data-group">${opts}</select></label><label>${tr('Measure','القياس')}<select id="data-metric"><option value="">${tr('Count rows','عدد السجلات')}</option>${opts}</select></label><button id="data-build">${tr('Generate private preview','توليد معاينة خاصة')}</button>`;cols.querySelector('#data-build').onclick=async()=>{try{const m=cols.querySelector('#data-metric').value;const d=await api('data-experience',{id,action:'preview',path:file.value,group:Number(cols.querySelector('#data-group').value),metric:m===''?null:Number(m)});show(d);msg.textContent=tr('Private preview saved','تم حفظ معاينة خاصة')}catch(e){msg.textContent=e.message}}}catch(e){msg.textContent=e.message}};el.querySelector('#data-hide').onclick=async()=>{await api('data-experience',{id,action:'hide'});msg.textContent=tr('Hidden','تم الإخفاء')};el.scrollIntoView({behavior:'smooth'})}catch(e){el.textContent=e.message}}

async function storageStudio(p){try{const s=await api('storage');p.innerHTML=`<div class="studio-banner"><div class="eyebrow">AXIS / ${tr('DATA VAULT','خزنة البيانات')}</div><h2>${tr('Hybrid file storage','التخزين الهجين للملفات')}</h2><p>${tr('Your projects keep their original formats. Metadata is JSON; descriptions are Markdown. GitHub sync requires a private repository.','تظل ملفات مشاريعك بصيغها الأصلية. البيانات الوصفية JSON والنصوص Markdown. المزامنة تحتاج مستودع GitHub خاصًا.')}</p></div><div class="grid"><article class="card"><h3>${tr('Storage','التخزين')}</h3><p>${tr('Local file checkpoint','لقطة ملفات محلية')}</p></article><article class="card"><h3>GitHub</h3><p>${s.configured?(s.pending?tr('Pending sync','مزامنة معلقة'):tr('Synchronized','متزامن')):tr('Not configured','غير متصل')}</p><p>${esc(s.lastSuccess||tr('No successful sync in this session','لا توجد مزامنة ناجحة في الجلسة الحالية'))}</p><p role="status">${esc(s.error||'')}</p><button id="sync-now" ${s.configured?'':'disabled'}>${tr('Sync now','زامن الآن')}</button><button id="sync-refresh">${tr('Refresh status','تحديث الحالة')}</button></article></div><div class="card"><h3>${tr('Configuration','الإعداد')}</h3><p>${tr('Set GITHUB_DATA_REPO and GITHUB_DATA_TOKEN on the server; use a separate private repository. Never expose credentials in the browser.','اضبط GITHUB_DATA_REPO و GITHUB_DATA_TOKEN في الخادم واستخدم مستودعًا خاصًا منفصلًا. لا تعرض المفاتيح في المتصفح.')}</p></div>`;p.querySelector('#sync-refresh').onclick=()=>storageStudio(p);p.querySelector('#sync-now').onclick=async e=>{e.target.disabled=true;try{await api('storage/sync',{});await storageStudio(p)}catch(e){msg(e)}}}catch(e){p.textContent=e.message}}

async function dataIndexStudio(p){try{const rows=await api('data-index');p.innerHTML=`<h2>${tr('Private data catalog','فهرس البيانات الخاص')}</h2><p>${tr('Automatic metadata only; original data stays private. Never upload credentials or confidential datasets without authorization.','فهرسة تلقائية للبيانات الوصفية فقط. الملفات خاصة. لا ترفع أسرارًا أو بيانات سرية دون إذن.')}</p>${rows.map(r=>`<section class="card"><h3>${esc(records.find(x=>x.id===r.projectId)?.title||r.projectId)}</h3>${r.files.map(f=>`<article><strong>${esc(f.path)}</strong><p>${esc(f.format)} · ${esc(f.status)} · ${f.bytes} B ${f.rowCount===undefined?'':' · '+f.rowCount+' '+tr('rows','صفوف')}</p><p>${esc((f.columns||f.tables||[]).join(' · '))}</p></article>`).join('')}</section>`).join('')||tr('No indexed files yet','لا توجد ملفات مفهرسة بعد')}`;}catch(e){p.textContent=e.message}}
